  ["Stereo module not installed."] = "Módulo estéreo não instalado.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Os hooks do motor não carregaram, então tudo abaixo está inativo e o headset está no caminho mono simples. Ou CyberpunkVR_StereoModuleEnable é 0, ou bin\\x64\\vrport_nostereo.txt existe. Veja a linha \"Stereo:\" em cyberpunkvrport.log.",
  ["LEFT"] = "ESQUERDO",
  ["RIGHT"] = "DIREITO",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Estéreo ativo  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Sem segundo olho no momento -> ambos os olhos recebem MAIN (mono)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Normal em menus e durante carregamentos. Se continuar assim no jogo: o componente VRCAM está desligado, ou vrcam.json aponta uma câmera que a entidade do jogador não tem.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Envio estéreo desligado -> ambos os olhos recebem MAIN (mono)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "idade do olho vrcam %u ms  (obsoleto após %u)   envios do olho %llu",
  ["vrcam eye: never produced a frame"] = "olho vrcam: nunca produziu um quadro",
  ["Send VRCAM to the %s EYE"] = "Enviar VRCAM para o OLHO %s",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Desligado = comportamento antigo, MAIN duplicado nos dois olhos.\nLigado = o olho %s recebe a cor final própria da visão VRCAM --\na mesma imagem que o espelho da área de trabalho mostra -- recodificada para o\nformato sRGB da swapchain e dimensionada para o tamanho do olho.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "cópias de instantâneo %llu   pulos %llu   acertos RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Limite de obsolescência do olho (ms)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Por quanto tempo o último quadro VRCAM continua utilizável. Depois disso o olho %s\nvolta para MAIN -- um olho congelado enquanto o outro se move\né muito pior de ver do que mono.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (segue o upscaler de MAIN, sem chave)",
  ["ON"] = "LIGADO",
  ["off"] = "desligado",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Ligado sempre que MAIN faz upscaling com DLSS: o vrcam ganha seu próprio\nviewport do Streamline e renderiza abaixo do seu alvo.\nDesligado com DLAA / TAA / sem upscaler. Altere nas configurações\ngráficas do jogo, não aqui.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Igualar a projeção do VRCAM à MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Componente VRCAM  (alternância RTTI: forçar LIGADO/DESLIGADO)",
  ["component %s   camera %s"] = "componente %s   câmera %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "nós de visão: main %llu   outros %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Espelho VRCAM  (janela separada, para captura)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Diagnóstico",
  ["Compact ADS camera telemetry (in-headset)"] = "Telemetria compacta da câmera ADS (no headset)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Um pequeno painel que fica visível depois de fechar o F10 e informa o que o MOTOR fez com a câmera ao levantar a mira:\ndelta e pico em centímetros, direita/frente/cima na base da própria direção, em relação a uma referência capturada atirando do quadril.\nO envio estéreo não é afetado.",
  ["Telemetry X"] = "Telemetria X",
  ["Telemetry Y"] = "Telemetria Y",
  ["Normalised position in the eye image"] = "Posição normalizada na imagem do olho",
  ["Stereo logging -> cyberpunkvrport.log"] = "Registro estéreo -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Instantâneo consolidado da imagem final do VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Desligado = ler diretamente o alvo temporário do motor. Esse alvo é uma\nalocação do frame graph que uma passada posterior reaproveita, o que\nfazia a imagem alternar entre clara e escura. Deixe ligado.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Instantâneo no nó de tonemap em vez de RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "Profiler de CPU dos nós  (ms próprios+incl. por nó)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "quadro %.2f ms   despacho: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Auditoria de nós -> registro  (reinicia a janela)",
  ["top %d by self ms/frame   (main | vrcam)"] = "top %d por ms próprios/quadro   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Direção -- mãos no volante",
  ["Grab the wheel with the grips"] = "Segurar o volante com os botões de pegada",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Ao DIRIGIR, leve uma mão até onde a animação de direção segura o\nvolante (ou o guidão) e aperte a pegada: o braço volta\npara a animação do próprio jogo -- mão no volante, dedos ao redor\ndele -- em vez de seguir o controle. Solte a pegada e ele volta\npara a sua mão.\n\nCada mão é independente: segure o volante com uma e mantenha a outra em\numa arma. Enquanto uma mão está no volante, essa pegada não faz mais nada (não\nsaca do coldre nem pega o carregador).",
  ["Grab radius (m)"] = "Raio de pegada (m)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Quão perto sua mão precisa estar da mão animada para que a\npegada conte como segurar o volante. Maior = mais fácil pegar um\nvolante que você não vê; grande demais e qualquer pegada no carro segura o volante.",
  ["Car full lock at (deg)"] = "Esterço total em (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Sensibilidade do volante: rotação da mão da posição de pegada até o esterço total.\nUma mão usa um cubo calibrado onde você segura; duas usam a linha que as liga.\nAdicionar ou soltar uma mão mantém o esterço atual.\n180 = meia volta até cada batente (padrão). Menor = mais sensível.\nO volante da cabine tem o dobro do curso nativo; o esterço das rodas não muda.\nO curso além do esterço total mantém a mesma posição neutra.",
  ["Steering deadzone (deg)"] = "Zona morta da direção (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Inclinação em torno do centro que não esterça nada.\nAumente se o carro puxar enquanto você segura o volante reto;\ncada grau aqui é um grau de volante morto fora do centro.\nA faixa completa ainda termina em \"Esterço total em\", então ampliar a\nzona morta não faz a direção saltar.",
  ["Steering prediction"] = "Previsão da direção",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "Antecipa suavemente uma curva contínua a partir do movimento recente da mão.\nLimitada a 8 ms e 0.5°; o neutro não muda.\nA previsão para numa pausa, inversão ou troca de pegada.\nDesligada por padrão. Ela não consegue antecipar o início de uma curva.",
  ["Prediction horizon (ms)"] = "Horizonte de previsão (ms)",
  ["Horn -- hand on the wheel hub"] = "Buzina -- mão no centro do volante",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Ao DIRIGIR, coloque uma mão no MEIO do volante -- onde você\nbateria numa buzina de verdade -- e o carro buzina enquanto ela ficar ali.\nSem pegada; uma mão SEGURANDO o volante nunca buzina.",
  ["Horn hub radius (m)"] = "Raio do centro da buzina (m)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Quão perto do centro do volante a mão conta como no cubo.\nMaior = mais fácil achar a buzina sem olhar; grande demais\ne alcança o aro, então toda pegada buzina.",
  ["Trigger fires the gun while driving"] = "O gatilho atira ao dirigir",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Saque uma arma no banco do motorista e o GATILHO DIREITO deixa de ser o\nacelerador e vira a arma: dirija com a mão esquerda no volante e\natire com a direita.\n\nO acelerador TRAVA no valor que tinha quando a arma saiu, então o\ncarro continua andando, e o ANALÓGICO ESQUERDO frente/trás ajusta essa velocidade enquanto\nvocê atira. Guarde a arma e o gatilho volta a ser o acelerador.\n\nCom a arma em mãos, o frente/trás do analógico esquerdo fica com o\najuste: sem inclinar / balançar e sem gesto de direção automática até guardar a arma.",
  ["Throttle trim rate (/s)"] = "Taxa de ajuste do acelerador (/s)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Quanto do curso total do acelerador o analógico esquerdo adiciona ou\nremove por segundo com uma arma em mãos.\n0.5 = dois segundos segurando para ir da marcha lenta ao fundo.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "direção %d   no volante  L %d R %d   pegada  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "esterço  %+.1f°  ->  analógico %+.2f     buzina  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "DESLOCAMENTO DA CÂMERA SENTADO",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Os deslocamentos da cabeça em GERAL são uma calibração de pé. Sentado, a câmera de veículo\ndo jogo já está onde deveria -- por isso o port descarta\nseus dois ajustes automáticos em um veículo -- então um deslocamento de pé tira a visão\ndo assento em vez de corrigi-la.\n\nEstes três são somados aos controles da cabeça enquanto você está em um veículo e\nignorados assim que você sai, para ajustar o carro e a rua\nseparadamente. Zero = o carro mantém exatamente o deslocamento atual.",
  ["Car Head X right"] = "Cabeça no carro X direita",
  ["Car Head Y forward"] = "Cabeça no carro Y frente",
  ["Car Head Z up"] = "Cabeça no carro Z cima",
  ["   (window combat: use GENERAL > Head offsets)"] = "   (combate pela janela: use GERAL > deslocamentos da cabeça)",
