  ["GENERAL"] = "GERAL",
  ["CAS Sharpening"] = "Nitidez CAS",
  ["Contrast-adaptive sharpening for both eyes. 0 = off, 1 = full strength. Disabled automatically with game DLAA."] = "Nitidez adaptativa ao contraste para os dois olhos. 0 = desligada, 1 = intensidade total. Desativada automaticamente com o DLAA do jogo.",
  ["FIXED FOVEATED RENDERING"] = "RENDERIZAÇÃO FOVEADA FIXA",
