  ["Performance"] = "Desempenho",
  ["The center follows game DLSS/DLAA. Peripheral DLAA uses 100%% / 75%% / 50%% of the game's render resolution."] = "O centro segue o DLSS/DLAA do jogo. O DLAA periférico usa 100%% / 75%% / 50%% da resolução de renderização do jogo.",
  ["Center width"] = "Largura do centro",
  ["Full-quality region width as a percentage of each eye image."] = "Largura da área de qualidade total como porcentagem da imagem de cada olho.",
  ["Center height"] = "Altura do centro",
  ["Full-quality region height as a percentage of each eye image."] = "Altura da área de qualidade total como porcentagem da imagem de cada olho.",
  ["Center offset X"] = "Deslocamento do centro X",
  ["Percentage of eye-image width. Negative = left, positive = right."] = "Porcentagem da largura da imagem do olho. Negativo = esquerda, positivo = direita.",
  ["Center offset Y"] = "Deslocamento do centro Y",
  ["Percentage of eye-image height. Negative = up, positive = down toward the hands."] = "Porcentagem da altura da imagem do olho. Negativo = cima, positivo = baixo, em direção às mãos.",
  ["Show region boundary"] = "Mostrar limite da área",
  ["DLSS GPU: native %.2f ms / foveated %.2f ms"] = "DLSS GPU: nativo %.2f ms / foveado %.2f ms",
  ["Shared sun shadows"] = "Sombras do sol compartilhadas",
  ["Render sun cascades once for both eyes. Shadow quality and distance remain controlled by the game."] = "Renderiza as cascatas do sol uma vez para os dois olhos. A qualidade e a distância das sombras continuam com o jogo.",
  ["Scope lens stabilization"] = "Estabilização da lente da mira",
  ["Magnifying scope lenses while the view moves: share of the stabilised image (percent). Higher: no blinking of lights and grates, softer. 0 = off. Standing still the lens is untouched."] = "Lentes de aumento das miras enquanto a visão se move: parcela da imagem estabilizada (porcentagem). Maior: sem piscar de luzes e grades, mais suave. 0 = desligado. Parado, a lente não muda.",
  ["VARIABLE RATE SHADING"] = "SOMBREAMENTO DE TAXA VARIÁVEL",
  ["Peripheral shading"] = "Sombreamento periférico",
  [" 2 x 2"] = " 2 x 2",
  [" 4 x 4"] = " 4 x 4",
  ["Opaque scene materials in both eyes. The center stays 1 x 1. Unsupported 4 x 4 falls back to 2 x 2."] = "Materiais opacos da cena nos dois olhos. O centro fica em 1 x 1. Sem suporte, 4 x 4 volta para 2 x 2.",
  ["Unavailable: GPU resource error"] = "Indisponível: erro de recurso da GPU",
  ["VRS Tier 2 unavailable"] = "VRS Tier 2 indisponível",
  ["Preparing"] = "Preparando",
  ["%s | %u px tiles"] = "%s | blocos de %u px",
  ["4 x 4"] = "4 x 4",
  ["2 x 2"] = "2 x 2",
  ["HIDDEN AREA MASK"] = "MÁSCARA DE ÁREA OCULTA",
  ["Mask lens edges"] = "Mascarar bordas das lentes",
  ["Skips shading the parts of each eye image the lens never shows. The visible area is unchanged."] = "Deixa de sombrear as partes da imagem de cada olho que a lente nunca mostra. A área visível não muda.",
  ["Visible radius"] = "Raio visível",
  ["Size of the shaded area as a percentage of the eye's field of view: 100%% touches its edges, 141%% masks nothing inside it.\nLower it until a dark border appears at the edge of the lens, then raise it until the border is gone."] = "Tamanho da área sombreada como porcentagem do campo de visão do olho: 100%% toca as bordas, 141%% não mascara nada dentro.\nDiminua até aparecer uma borda escura na beira da lente e depois aumente até ela sumir.",
  ["Waiting for the scene depth"] = "Aguardando a profundidade da cena",
  ["Masked %.1f %% / %.1f %% of pixels (MAIN / VRCAM)"] = "Mascarado %.1f %% / %.1f %% dos pixels (MAIN / VRCAM)",
  ["GAME MENUS"] = "MENUS DO JOGO",
  ["VR menu quad"] = "Plano do menu VR",
  ["VR menu FOV"] = "FOV do menu VR",
  ["Tracking / Camera"] = "Rastreamento / câmera",
  ["Locomotion direction is set in the Controls tab."] = "A direção de locomoção é definida na aba Controles.",
  ["Disable Mouse Y (Pitch)"] = "Desativar mouse Y (arfagem)",
  ["Suppress mouse/right-stick pitch so only the HMD controls\nvertical look. Applied by the CET VRIK mod and the\nXInput merge. On by default."] = "Suprime a arfagem do mouse/analógico direito para que só o HMD controle\no olhar vertical. Aplicado pelo mod CET VRIK e pela\nfusão XInput. Ligado por padrão.",
  ["Head X right"] = "Cabeça X direita",
  ["Head Y forward"] = "Cabeça Y frente",
  ["Head Z up"] = "Cabeça Z cima",
  ["Debug Gizmos"] = "Gizmos de depuração",
  ["Raw hand overlay / debug gizmos:"] = "Overlay bruto das mãos / gizmos de depuração:",
  ["Enable hand overlay"] = "Ativar overlay das mãos",
  ["Draw 3D hand proxy"] = "Desenhar mão 3D",
  ["Draw debug wire/axes"] = "Desenhar linhas/eixos de depuração",
  ["Locator scale"] = "Escala dos localizadores",
  ["Verbose log (spammy diag)"] = "Registro detalhado (muito diagnóstico)",
  ["Off by default for a clean cyberpunkvrport.log. Enable only\nwhen capturing ClipCursor / depth / hook diagnostics."] = "Desligado por padrão para um cyberpunkvrport.log limpo. Ative somente\nao capturar diagnósticos de ClipCursor / profundidade / hooks.",
  ["FRAMEGEN"] = "GER. QUADROS",
  ["Enable frame generation"] = "Ativar geração de quadros",
  ["While frame generation is enabled, hand smoothing runs at its rate times xr_hand_lerp_framegen_scale (1.5; 0 turns it off)."] = "Com a geração de quadros ativa, a suavização das mãos roda na sua taxa vezes xr_hand_lerp_framegen_scale (1.5; 0 desliga).",
  ["Frame generator"] = "Gerador de quadros",
  ["FidelityFX"] = "FidelityFX",
  ["NVIDIA OFA + FidelityFX"] = "NVIDIA OFA + FidelityFX",
  ["NVIDIA DLSS Frame Generation"] = "NVIDIA DLSS Frame Generation",
  ["DLSS Frame Generation is not available here (%s); FidelityFX is used."] = "DLSS Frame Generation não está disponível aqui (%s); o FidelityFX é usado.",
  ["NVIDIA optical flow is not available on this GPU; FidelityFX optical flow is used."] = "O fluxo óptico da NVIDIA não está disponível nesta GPU; o fluxo óptico do FidelityFX é usado.",
  ["NVIDIA quality"] = "Qualidade NVIDIA",
  ["Fast (performance)"] = "Rápido (desempenho)",
  ["Medium (balanced)"] = "Médio (equilibrado)",
  ["Slow (best)"] = "Lento (melhor)",
  ["Optical flow"] = "Fluxo óptico",
  ["Off (game vectors only)"] = "Desligado (só vetores do jogo)",
  ["The game's motion vectors already describe almost all motion; optical flow adds GPU time\nand memory for what they miss (some particles and effects)."] = "Os vetores de movimento do jogo já descrevem quase todo o movimento; o fluxo óptico acrescenta tempo de GPU\ne memória para o que eles perdem (algumas partículas e efeitos).",
  ["NVIDIA's frame generation model on the game's motion vectors and depth. Highest quality, RTX 40/50."] = "O modelo de geração de quadros da NVIDIA sobre os vetores de movimento e a profundidade do jogo. Qualidade máxima, RTX 40/50.",
  ["Adaptive real-frame pacing"] = "Ritmo adaptativo de quadros reais",
  ["Up to half headset refresh. Leaves more GPU time for generated frames when adjacent real frames are being missed."] = "Até metade da taxa de atualização do headset. Deixa mais tempo de GPU para os quadros gerados quando quadros reais vizinhos são perdidos.",
  ["Uses game motion vectors and depth in both eyes. Adds one intermediate frame between real frames."] = "Usa os vetores de movimento e a profundidade do jogo nos dois olhos. Adiciona um quadro intermediário entre quadros reais.",
  ["HUD"] = "HUD",
  ["Enable HUD panel"] = "Ativar painel do HUD",
  ["Head / free-look cone"] = "Cabeça / cone de visão livre",
  ["Follow"] = "Seguir",
  ["Catch up beyond the cone, or after 3 seconds at rest when the yaw offset is over 10 degrees inside it."] = "Alcança além do cone, ou após 3 segundos parado se o desvio de guinada passar de 10° dentro dele.",
  ["HUD FOV"] = "FOV do HUD",
  ["Stereo depth"] = "Profundidade estéreo",
  ["Off: the HUD has the same direction in both eyes.\nOn: place it at the selected physical depth."] = "Desligado: o HUD tem a mesma direção nos dois olhos.\nLigado: coloca-o na profundidade física escolhida.",
  ["Depth"] = "Profundidade",
  ["Brightness"] = "Brilho",
  ["Shadow / outline"] = "Sombra / contorno",
  ["Glow"] = "Brilho externo",
  ["INTERACTIONS / DIALOGS"] = "INTERAÇÕES / DIÁLOGOS",
  ["World-space interactions / dialogs"] = "Interações / diálogos no espaço",
  ["Interaction free-look cone"] = "Cone de visão livre das interações",
  ["Loot free-look cone"] = "Cone de visão livre do saque",
  ["Used while the loot panel and item description are visible. Default: 10 degrees."] = "Usado enquanto o painel de saque e a descrição do item estão visíveis. Padrão: 10°.",
  ["Interaction distance"] = "Distância das interações",
  ["Interaction FOV"] = "FOV das interações",
  ["Interaction prompts and dialog choices share this panel. It follows only beyond the cone; no delayed catch-up at rest."] = "Avisos de interação e escolhas de diálogo dividem este painel. Ele só acompanha além do cone; sem alcance atrasado quando parado.",
  ["Element"] = "Elemento",
  ["Not currently visible in gameplay; settings are still saved."] = "Não visível no jogo agora; as configurações são salvas mesmo assim.",
  ["Show element"] = "Mostrar elemento",
  ["Horizontal offset"] = "Deslocamento horizontal",
  ["Vertical offset"] = "Deslocamento vertical",
  ["Size"] = "Tamanho",
  ["Opacity"] = "Opacidade",
  ["Reset element"] = "Redefinir elemento",
  ["Reset all elements"] = "Redefinir todos os elementos",
  ["CONTROLS"] = "CONTROLES",
  ["DRIVING"] = "DIREÇÃO",
  ["BINDINGS"] = "ATRIBUIÇÕES",
  ["Movement, weapon aiming and physical interaction shortcuts."] = "Atalhos de movimento, mira e interação física.",
  ["Hand aim  (off = Decoupled VR Head Aim)"] = "Mira com a mão  (desligado = mira VR com a cabeça desacoplada)",
  ["ON (Hand Aim): the controller points the weapon and VRIK drives the arms.\nOFF (Decoupled VR Head Aim): the WEAPON follows your head instead, the game\nkeeps owning its position and its ADS animations, and VRIK stands down for\nthe weapon arm. Either way the shot leaves the real muzzle, for guns and\nprojectiles alike, and free-look while aiming is preserved."] = "LIGADO (mira com a mão): o controle aponta a arma e o VRIK move os braços.\nDESLIGADO (mira com a cabeça desacoplada): a ARMA segue a sua cabeça, o jogo\nmantém a posição dela e as animações de ADS, e o VRIK libera\no braço da arma. Em ambos os casos o tiro sai do cano real, tanto para balas\nquanto para projéteis, e a visão livre ao mirar é preservada.",
  ["Weapon Aim laser dot (where the bullet hits)"] = "Ponto laser da arma (onde a bala acerta)",
  ["Red dot projected from the actual weapon muzzle direction through the\ngame camera -- marks exactly where the bullet will fly."] = "Ponto vermelho projetado da direção real do cano através da\ncâmera do jogo -- marca exatamente para onde a bala vai.",
  ["Controller vibration"] = "Vibração dos controles",
  ["Haptics: every round by weapon class (handgun, rifle, shotgun, sniper),\nmelee block and parry, bullet block and deflect, reaching a belt element,\npulling a grenade pin. Two-handed grip: both hands; one hand: one."] = "Háptica: cada disparo pela classe da arma (pistola, fuzil, escopeta, rifle de precisão),\nbloqueio e aparo corpo a corpo, bloqueio e desvio de balas, alcançar um item do cinto,\npuxar o pino de uma granada. Pegada com duas mãos: ambas; com uma mão: uma.",
  ["Vibration strength"] = "Intensidade da vibração",
  ["Enable VR -> XInput merge"] = "Ativar fusão VR -> XInput",
  ["OR the VR controller state into XInput gamepad 0 every poll.\nOff = the game only sees a physical pad / nothing."] = "Combina (OR) o estado dos controles VR com o controle XInput 0 a cada leitura.\nDesligado = o jogo só vê um controle físico / nada.",
  ["Weapon holsters (reach + right grip)"] = "Coldres de armas (alcançar + pegada direita)",
  ["Immersive holsters"] = "Coldres imersivos",
  ["ON  - equip is chosen by the VISUAL holster you reach for:\n      over the right shoulder = primary weapon (rifle / sniper),\n      hip with a katana = melee, hip with a pistol = sidearm.\nOFF - ignore visual holsters, fixed slot per zone:\n      over-shoulder = EquipmentSlot1, right hip = Slot2, left hip = Slot3.\nReach to the zone and squeeze the RIGHT grip to equip / unequip."] = "ON  - a arma é escolhida pelo coldre VISÍVEL que você alcança:\n      sobre o ombro direito = arma principal (fuzil / precisão),\n      quadril com katana = corpo a corpo, quadril com pistola = arma secundária.\nOFF - ignora coldres visíveis, slot fixo por zona:\n      sobre o ombro = EquipmentSlot1, quadril direito = Slot2, quadril esquerdo = Slot3.\nAlcance a zona e aperte a pegada DIREITA para equipar / guardar.",
  ["Locomotion direction"] = "Direção de locomoção",
  ["Analog movement"] = "Movimento analógico",
  ["On: speed follows left-stick travel. Off: the current fixed-speed movement (default).\nVehicle controls keep their existing response."] = "Ligado: a velocidade segue o curso do analógico esquerdo. Desligado: o movimento atual de velocidade fixa (padrão).\nOs controles de veículos mantêm a resposta atual.",
  ["Left stick deadzone"] = "Zona morta do analógico esquerdo",
  ["Right stick deadzone"] = "Zona morta do analógico direito",
  ["Full input threshold"] = "Limite de entrada total",
  ["Raw travel that produces full analog input and activates sprint, dash and crouch.\nThe usable travel between the deadzone and this threshold maps to 0-100%%."] = "Curso bruto que gera entrada analógica total e ativa corrida, esquiva e agachamento.\nO curso útil entre a zona morta e este limite equivale a 0-100%%.",
  ["Game (camera)"] = "Jogo (câmera)",
  ["HMD (head)"] = "HMD (cabeça)",
  ["Left hand"] = "Mão esquerda",
  ["Right hand"] = "Mão direita",
  ["Move source"] = "Origem do movimento",
  ["Game     - left stick walks the way the camera faces (vanilla).\nHMD      - left stick walks the way the headset faces.\nLeft/Right hand - walks the way the chosen controller points.\nVehicles always keep game heading."] = "Jogo     - o analógico esquerdo anda para onde a câmera olha (original).\nHMD      - o analógico esquerdo anda para onde o headset olha.\nMão esq./dir. - anda para onde o controle escolhido aponta.\nVeículos sempre mantêm a direção do jogo.",
  ["Breaststroke swimming"] = "Nado peito",
  ["Physical crouch"] = "Agachamento físico",
  ["Physical crouch depth"] = "Profundidade do agachamento físico",
  ["%.0f cm"] = "%.0f cm",
  ["Height loss after the measured lean. Standing back up releases physical crouch."] = "Perda de altura após a inclinação medida. Ficar de pé libera o agachamento físico.",
  ["In water: reach forward with both hands, sweep out and pull back.\nMovement begins during the pull. Gentle strokes swim normally; fast pulls boost.\nSwim where the headset points, including up/down; no stick needed.\nTo rise, raise separated hands to chest level and push both down.\nRepeat strokes to keep moving. Pull the left stick back to stop."] = "Na água: estenda as duas mãos à frente, abra para os lados e puxe para trás.\nO movimento começa durante a puxada. Braçadas suaves nadam normalmente; puxadas rápidas dão impulso.\nNade para onde o headset aponta, inclusive para cima/baixo; sem analógico.\nPara subir, levante as mãos afastadas à altura do peito e empurre ambas para baixo.\nRepita as braçadas para continuar. Puxe o analógico esquerdo para trás para parar.",
  ["Ladder grip climbing"] = "Escalar escadas com pegada",
  ["Grip a side rail or rung. Pull the hand down to climb up,\nor move it up to climb down. Release to stop. Native pelvis and legs stay on the ladder."] = "Segure um corrimão lateral ou um degrau. Puxe a mão para baixo para subir,\nou mova-a para cima para descer. Solte para parar. A pelve e as pernas nativas ficam na escada.",
  ["Auto finish near ladder top"] = "Concluir automaticamente no topo da escada",
  ["After an upward pull near the top, finish climbing even when grips are released.\nMove the stick or push a held hand upward to cancel."] = "Após uma puxada para cima perto do topo, conclui a subida mesmo com as pegadas soltas.\nMova o analógico ou empurre para cima uma mão segurando para cancelar.",
  ["Ladder finish distance"] = "Distância de conclusão da escada",
  ["Turning (right stick)"] = "Giro (analógico direito)",
  ["Snap turn"] = "Giro em etapas",
  ["Convert the right-stick X axis into discrete snap pulses\ninstead of smooth rotation. Helps with motion sickness."] = "Converte o eixo X do analógico direito em etapas de giro\nem vez de rotação suave. Ajuda contra enjoo.",
  ["Snap angle"] = "Ângulo da etapa",
  ["STEREO"] = "ESTÉREO",
  ["PERFORMANCE"] = "DESEMPENHO",
  ["NVIDIA Reflex"] = "NVIDIA Reflex",
  ["Game setting"] = "Configuração do jogo",
  ["Off (higher FPS)"] = "Desligado (mais FPS)",
  ["On (lower latency)"] = "Ligado (menor latência)",
  ["On + Boost"] = "Ligado + Boost",
  ["Off can improve GPU utilization and FPS, but may increase input latency."] = "Desligado pode melhorar o uso da GPU e o FPS, mas pode aumentar a latência de entrada.",
  ["On"] = "Ligado",
  ["Waiting for renderer"] = "Aguardando o renderizador",
  ["Applied: %s"] = "Aplicado: %s",
  ["STEREO VIEW"] = "VISÃO ESTÉREO",
  ["Mono mode"] = "Modo mono",
  ["One picture for both eyes, drawn once from the centre of the head:\nno depth, the most frames. Engine stereo and the second view are off."] = "Uma imagem para os dois olhos, renderizada uma vez a partir do centro da cabeça:\nsem profundidade, o máximo de quadros. Estéreo do motor e segunda visão desligados.",
  ["Restart the game to apply"] = "Reinicie o jogo para aplicar",
  ["Motion prediction (ms)"] = "Previsão de movimento (ms)",
  ["%.1f ms"] = "%.1f ms",
  ["Forward-predicts the head pose by this many ms using head\nvelocity, hiding render-to-photon latency. 0 = off.\nTune up until motion feels responsive without overshoot."] = "Prevê a pose da cabeça esses ms à frente pela sua\nvelocidade, escondendo a latência da renderização até os fótons. 0 = desligado.\nAumente até o movimento ficar responsivo sem passar do ponto.",
  ["Stereo separation x"] = "Separação estéreo x",
  ["Personal fine-tune on the auto IPD. 1.0 = calibrated natural\nseparation, auto-scaled to the headset's runtime IPD. Nudge\n0.8-1.2 for taste; crank to 3-5x to exaggerate depth and make\nthe eye alternation obvious on the flat monitor for testing."] = "Ajuste pessoal do IPD automático. 1.0 = separação natural\ncalibrada, escalada para o IPD do runtime do headset. Ajuste\n0.8-1.2 a gosto; 3-5x exagera a profundidade e deixa\na alternância dos olhos visível no monitor plano para testes.",
  ["World scale"] = "Escala do mundo",
  ["Scales eye separation AND head translation together.\nLower it (e.g. 0.8) to make the world look\nBIGGER / yourself smaller; raise to shrink the world. Use this if V\nand NPCs feel too large."] = "Escala juntas a separação dos olhos E a translação da cabeça.\nDiminua (ex. 0.8) para o mundo parecer\nMAIOR / você menor; aumente para encolher o mundo. Use se V\ne os NPCs parecerem grandes demais.",
  ["IPD scale"] = "Escala do IPD",
  ["Eye-separation multiplier on the runtime IPD. 1.0 = the neutral\nbaseline (+-0.033 m on a typical headset).\nAffects stereo depth (diorama vs giant), NOT the monocular size."] = "Multiplicador da separação dos olhos sobre o IPD do runtime. 1.0 = a base\nneutra (+-0.033 m em um headset típico).\nAfeta a profundidade estéreo (diorama ou gigante), NÃO o tamanho monocular.",
  ["Reuse last clean frame"] = "Reutilizar o último quadro limpo",
  ["On stale ticks, re-submit the last clean captured eye and let\nthe compositor reproject it, instead of warping stale content\nagain. May lower submit rate\ntoward the capture rate. Off = always warp the stale eye."] = "Em ticks obsoletos, reenvia o último olho capturado limpo e deixa\no compositor reprojetá-lo, em vez de distorcer de novo\no conteúdo obsoleto. Pode reduzir a taxa de envio\nem direção à taxa de captura. Desligado = sempre distorcer o olho obsoleto.",
  ["Asymmetric projection"] = "Projeção assimétrica",
  ["ON: each eye renders exactly its own off-centre lens window\n(more of the panel used, square pixels).\nOFF: the symmetric frustum sized to the widest half-angle."] = "ON: cada olho renderiza exatamente sua própria janela de lente descentralizada\n(mais do painel usado, pixels quadrados).\nOFF: o frustum simétrico dimensionado pelo semiângulo mais largo.",
  ["AVATAR"] = "AVATAR",
  ["VR shortcuts and default game actions. Button names follow the Touch / Xbox convention; game actions use your controller bindings."] = "Atalhos de VR e ações padrão do jogo. Os nomes dos botões seguem a convenção Touch / Xbox; as ações do jogo usam as suas atribuições do controle.",
  ["LEFT STICK"] = "ANALÓGICO ESQUERDO",
  ["Move. Hold fully forward for 0.2 seconds to sprint."] = "Mover. Segure totalmente para a frente por 0.2 segundo para correr.",
  ["RIGHT STICK  Left / right"] = "ANALÓGICO DIREITO  Esquerda / direita",
  ["Turn. Uses your snap-turn setting."] = "Girar. Usa a sua configuração de giro em etapas.",
  ["RIGHT STICK  Full up"] = "ANALÓGICO DIREITO  Todo para cima",
  ["Dash / dodge once per push."] = "Investida / esquiva, uma vez por empurrão.",
  ["RIGHT STICK  Full down"] = "ANALÓGICO DIREITO  Todo para baixo",
